HEXDIGITS = b'0123456789abcdefABCDEF'
DIGITS = b'0123456789'
VISIBLE = bytes(range(33, 127))
VALUE_CHARS = bytes(range(32, 127)) + bytes([9])
FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')
LENGTH = b'content-length'
ENCODING = b'transfer-encoding'
VERSION = b'HTTP/1.1'


class Reader:
    """Logical byte stream: structural hashing plus bounded direct access."""

    __slots__ = ('node', 'length', 'data')

    def __init__(self, node):
        self.node = node
        self.length = node.length
        self.data = None
        if node.length and node.length <= MATERIALIZE_LIMIT:
            if isinstance(node, Lit):
                self.data = node.data
            else:
                self.data = materialize(node)

    def at(self, index):
        data = self.data
        return data[index] if data is not None else byte_at(self.node, index)

    def block(self, start, end):
        data = self.data
        return data[start:end] if data is not None else window(self.node, start, end)

    def find_lf(self, start, stop):
        data = self.data
        return data.find(b'\n', start, stop) if data is not None else \
            _scan_lf(self.node, start, stop)

    def region(self, start, end):
        return hash_range(self.node, start, end)

    def release(self):
        """Drop the expanded copy once the channel has been framed."""
        self.data = None


def _scan_lf(node, start, stop):
    if isinstance(node, Lit):
        return node.data.find(b'\n', start, stop)
    if start >= stop:
        return -1
    if isinstance(node, Cat):
        previous = 0
        for position, bound in enumerate(node.offsets):
            if bound <= start:
                previous = bound
                continue
            if stop <= previous:
                break
            left = max(start, previous)
            right = min(stop, bound)
            found = _scan_lf(node.parts[position], left - previous, right - previous)
            if found >= 0:
                return previous + found
            previous = bound
        return -1
    block = window(node, start, stop)
    found = block.find(b'\n')
    return -1 if found < 0 else start + found


def encode_fields(fields):
    out = bytearray(len(fields).to_bytes(8, 'big'))
    for name, value in fields:
        out += len(name).to_bytes(8, 'big')
        out += name
        out += len(value).to_bytes(8, 'big')
        out += value
    return bytes(out)


def fingerprint_bytes(data):
    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}


def _visible(data):
    """Every byte is ASCII visible (33..126); C-speed set membership."""
    return not data.translate(None, VISIBLE)


